#!/usr/bin/env python3

import json
import sys
from pathlib import Path

ROOT_DIR = Path(__file__).resolve().parent.parent
BUILD_DIR = ROOT_DIR / "build"
DB_PATH = BUILD_DIR / "formatdb.json"

COMMON_TEMPLATE = """\
# Auto-generated by scripts/gen-format.py. Do not edit manually.

SETS = {sets_repr}
BITMASKS = {bitmasks_repr}


def format_set_value(val: int, mapping: dict[int, str], size: int) -> str:
    unsigned = val & ((1 << (size * 8)) - 1)
    return mapping.get(unsigned, str(unsigned))


def format_bitmask_value(val: int, mapping: dict[int, str], size: int) -> str:
    unsigned = val & ((1 << (size * 8)) - 1)
    if unsigned == 0:
        return mapping.get(0, "0")

    parts = []
    for bit in range(unsigned.bit_length()):
        mask = 1 << bit
        if unsigned & mask:
            parts.append(mapping.get(mask, f"0x{{mask:x}}"))

    return " | ".join(parts)
"""

GDB_TEMPLATE = COMMON_TEMPLATE + """

import gdb # type: ignore


class SetPrinter:
    def __init__(self, value, mapping):
        self.value = value
        self.mapping = mapping

    def to_string(self):
        return format_set_value(int(self.value), self.mapping, self.value.type.sizeof)


class BitmaskPrinter:
    def __init__(self, value, mapping):
        self.value = value
        self.mapping = mapping

    def to_string(self):
        return format_bitmask_value(int(self.value), self.mapping, self.value.type.sizeof)


def gdb_lookup(value):
    unqualified = value.type.unqualified()
    type_name = unqualified.name or str(unqualified)

    if type_name in SETS:
        return SetPrinter(value, SETS[type_name])
    if type_name in BITMASKS:
        return BitmaskPrinter(value, BITMASKS[type_name])
    return None


gdb.pretty_printers.append(gdb_lookup)
"""

LLDB_TEMPLATE = COMMON_TEMPLATE + """

import lldb


def lldb_format_set(valobj, internal_dict):
    val = valobj.GetValueAsUnsigned(0)
    type_name = valobj.GetType().GetUnqualifiedType().GetName()
    return format_set_value(val, SETS.get(type_name, {{}}), valobj.GetByteSize())


def lldb_format_bitmask(valobj, internal_dict):
    val = valobj.GetValueAsUnsigned(0)
    type_name = valobj.GetType().GetUnqualifiedType().GetName()
    return format_bitmask_value(val, BITMASKS.get(type_name, {{}}), valobj.GetByteSize())


def __lldb_init_module(debugger, internal_dict):
    category = debugger.GetCategory("PAL")
    category.SetEnabled(True)

    for type_name in SETS:
        summary = lldb.SBTypeSummary.CreateWithFunctionName(f"{{__name__}}.lldb_format_set")
        category.AddTypeSummary(lldb.SBTypeNameSpecifier(type_name, False), summary)

    for type_name in BITMASKS:
        summary = lldb.SBTypeSummary.CreateWithFunctionName(f"{{__name__}}.lldb_format_bitmask")
        category.AddTypeSummary(lldb.SBTypeNameSpecifier(type_name, False), summary)
"""


def load_db():
    if not DB_PATH.exists():
        sys.exit(
            f"[format] Error: {DB_PATH} not found. Run scripts/gen-formatdb.py first.")

    raw = json.loads(DB_PATH.read_text(encoding="utf-8"))

    sets = {}
    for type_name, mapping in raw.get("sets", {}).items():
        int_map = {}
        for k, v in mapping.items():
            int_map[int(k)] = v
        sets[type_name] = int_map

    bitmasks = {}
    for type_name, mapping in raw.get("bitmasks", {}).items():
        int_map = {}
        for k, v in mapping.items():
            int_map[int(k)] = v
        bitmasks[type_name] = int_map

    return sets, bitmasks


def format_dict(data: dict[str, dict[int, str]]) -> str:
    if not data:
        return "{}"

    lines = ["{"]
    for type_name, mapping in data.items():
        if not mapping:
            lines.append(f'    "{type_name}": {{}},')
            continue

        lines.append(f'    "{type_name}": {{')
        for val, macro in mapping.items():
            lines.append(f'        {val}: "{macro}",')
        lines.append("    },")

    lines.append("}")
    return "\n".join(lines)


def main():
    if len(sys.argv) < 2 or sys.argv[1].lower() not in ("gdb", "lldb"):
        sys.exit("Usage: python scripts/gen-format.py <gdb|lldb>")

    target = sys.argv[1].lower()
    sets, bitmasks = load_db()

    BUILD_DIR.mkdir(parents=True, exist_ok=True)
    template = GDB_TEMPLATE if target == "gdb" else LLDB_TEMPLATE
    out_path = BUILD_DIR / f"{target}-format.py"

    content = template.format(
        sets_repr=format_dict(sets),
        bitmasks_repr=format_dict(bitmasks),
    )

    out_path.write_text(content, encoding="utf-8")
    print(f"{target} format generated generated successfully")


if __name__ == "__main__":
    main()
